 28	function mockRequest(method: string, url: string, bodyJson?: unknown): IncomingMessage {
 29	    const req = new EventEmitter() as IncomingMessage;
 30	    (req as unknown as { method: string }).method = method;
 31	    (req as unknown as { url: string }).url = url;
 32	    (req as unknown as { destroy(): void }).destroy = () => {
 33	        req.emit('error', new Error('destroyed'));
 34	    };
 35	
 36	    process.nextTick(() => {
 37	        if (bodyJson !== undefined) {
 38	            req.emit('data', Buffer.from(JSON.stringify(bodyJson)));
 39	        }
 40	        req.emit('end');
 41	    });
 42	
 43	    return req;
 44	}
 45	
 46	interface MockResponse {
 47	    statusCode: number | undefined;
 48	    body: string;
 49	    res: ServerResponse;
 50	}
 51	
 52	function mockResponse(): MockResponse {
 53	    const mock: MockResponse = {
 54	        statusCode: undefined,
 55	        body: '',
 56	        res: null as unknown as ServerResponse,
 57	    };
 58	
 59	    const res = new EventEmitter() as unknown as ServerResponse;
 60	
 61	    (res as unknown as {
 62	        writeHead(status: number, headers?: Record<string, string | number>): void;
 63	    }).writeHead = (status: number) => {
 64	        mock.statusCode = status;
 65	    };
 66	
 67	    (res as unknown as { end(body?: string): void }).end = (body?: string) => {
 68	        mock.body = body ?? '';
 69	    };
 70	
 71	    mock.res = res;
 72	    return mock;
 73	}
